import{_ as a,c as p,o as e,a5 as r}from"./chunks/framework.DorIfSpC.js";const d=JSON.parse('{"title":"當世界開始重新洗牌，台灣在哪裡？——風傳媒「劇變與解方」論壇現場筆記","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/ai/風傳媒論壇_部落格_20260311"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/ai/風傳媒論壇_部落格_20260311"}],["meta",{"property":"og:title","content":"當世界開始重新洗牌，台灣在哪裡？——風傳媒「劇變與解方」論壇現場筆記 | 星智未來"}],["meta",{"name":"twitter:title","content":"當世界開始重新洗牌，台灣在哪裡？——風傳媒「劇變與解方」論壇現場筆記 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"當世界開始重新洗牌，台灣在哪裡？——風傳媒「劇變與解方」論壇現場筆記\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/ai/風傳媒論壇_部落格_20260311\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/ai/風傳媒論壇_部落格_20260311\\"}}"]]},"headers":[],"relativePath":"ai/風傳媒論壇_部落格_20260311.md","filePath":"ai/風傳媒論壇_部落格_20260311.md","lastUpdated":1783658382000}'),o={name:"ai/風傳媒論壇_部落格_20260311.md"};function n(i,t,l,s,h,c){return e(),p("div",null,[...t[0]||(t[0]=[r('<h1 id="當世界開始重新洗牌-台灣在哪裡-——風傳媒「劇變與解方」論壇現場筆記" tabindex="-1">當世界開始重新洗牌，台灣在哪裡？——風傳媒「劇變與解方」論壇現場筆記 <a class="header-anchor" href="#當世界開始重新洗牌-台灣在哪裡-——風傳媒「劇變與解方」論壇現場筆記" aria-label="Permalink to &quot;當世界開始重新洗牌，台灣在哪裡？——風傳媒「劇變與解方」論壇現場筆記&quot;">​</a></h1><blockquote><p>這場論壇真正在討論的，只有一個問題——台灣到底想成為什麼？</p></blockquote><p>2026年3月11日，台北。</p><p>風傳媒舉辦了一場以「劇變與解方」為題的論壇，副標是：美中爭霸下的關稅貨幣難題、晶片爭奪、AI狂潮。</p><p>六位講者，橫跨地緣政治、半導體產業、AI技術三個領域。</p><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 3 月 11 日</p><hr><h2 id="一、陳冲-問題已經很清楚了-答案呢" tabindex="-1">一、陳冲：問題已經很清楚了，答案呢？ <a class="header-anchor" href="#一、陳冲-問題已經很清楚了-答案呢" aria-label="Permalink to &quot;一、陳冲：問題已經很清楚了，答案呢？&quot;">​</a></h2><p>前行政院長陳冲的演講風格很隱諱，他不直接說結論，而是把材料一層一層疊上來，讓聽眾自己去連結。</p><p>他先診斷世界的現狀：川普讓規則死了。2025年美國自己的法院兩度裁定關稅違憲，川普的回應是罵法官「不愛國」——連美國自己的憲政秩序都在鬆動，更別說什麼國際規則。</p><p>然後他拿戰國史來類比現在的局勢。蘇秦推合縱，六國聯合抗秦；張儀推連橫，秦國各個擊破。他介紹了加拿大總理Carney這幾個月的動作——密集出訪印度、日本、澳洲，試圖推動加拿大—英國—CPTPP—EU的大聯盟。在陳冲的框架裡，Carney做的事就是現代版的合縱。</p><p>他給台灣列了五個選項：</p><ol><li><strong>Menu</strong>——成為別人桌上的菜</li><li><strong>Pawn</strong>——棋子</li><li><strong>Chess Master</strong>——主動佈局者</li><li><strong>Middle Power</strong>——中等強國</li><li><strong>Or Else？</strong>——留白</li></ol><p>五個選項放在投影片上，陳冲沒有替台灣做選擇。</p><p>Middle Power怎麼做？他說第一步是誠實地盤點自己的籌碼：台灣的真正優勢是什麼？石油？核彈？糧食？半導體？然後才能談怎麼合縱、怎麼進小多邊組織、怎麼在新秩序成形之前卡好位置。</p><p>整場演講，陳冲把問題問得很清楚。但答案，他留給台灣自己去想。</p><hr><h2 id="二、吳田玉-別怕晶片被搶-用它來槓桿世界" tabindex="-1">二、吳田玉：別怕晶片被搶，用它來槓桿世界 <a class="header-anchor" href="#二、吳田玉-別怕晶片被搶-用它來槓桿世界" aria-label="Permalink to &quot;二、吳田玉：別怕晶片被搶，用它來槓桿世界&quot;">​</a></h2><p>日月光半導體執行長吳田玉的切入點跟陳冲形成了有趣的對照。</p><p>他的核心論點：<strong>不要去爭奪晶片，要用晶片槓桿世界。</strong></p><p>他先指出一個現象：AI軟體的能力已經不是瓶頸了。真正卡住全球AI發展的是硬體——先進封裝、PCB、AI資料中心的系統整合能力。而這些，台灣全球第一。封裝測試第一、PCB第一、AI叢集的領先製造技術第一。</p><p>他用了兩個詞：<strong>投鼠忌器</strong>、<strong>禍福相倚</strong>。</p><p>台灣在供應鏈裡的位置，讓任何想施壓的一方都必須算清楚代價。地緣政治的壓力固然帶來不確定性，但同時也讓台灣的不可或缺性變得更加清晰。</p><p>然後他講量變到質變的概念：台灣半導體供應鏈每個環節獨立看都很強，但真正的護城河是這些環節加在一起的系統優化能力，這是別的地方複製不了的。2026年實際的半導體市佔數據，他說會大幅超越原先的預估。</p><p>台灣不應該把自己定位成零件供應商，而應該是系統整合者。掌握瓶頸的人才有定價權，而台灣現在掌握的瓶頸不只一個。</p><hr><h2 id="三、劉峻誠-石油美元時代要結束了" tabindex="-1">三、劉峻誠：石油美元時代要結束了 <a class="header-anchor" href="#三、劉峻誠-石油美元時代要結束了" aria-label="Permalink to &quot;三、劉峻誠：石油美元時代要結束了&quot;">​</a></h2><p>耐能智慧（Kneron）創辦人劉峻誠的演講，是我覺得整場論壇最有歷史縱深的一段。</p><p>他把過去八十年切成三個時代：</p><p><strong>1944到1971年</strong>：布列頓森林體系，美元錨定黃金，美國建立戰後金融秩序。</p><p><strong>1971到202X年</strong>：尼克森衝擊，美元脫鉤黃金，改綁石油。美國深入中東，所有的地緣博弈都服務於一件事——確保石油的美元定價權。這個體系讓美國可以大量發行美元，因為全世界都需要用美元買石油。</p><p><strong>202X年至今</strong>：石油美元體系走向終結，AI算力成為新的戰略資源。</p><p>他用伊朗舉例：伊朗擁有石油，但因為被制裁，石油換不成真正的戰略籌碼。擁有資源跟能夠運用資源，是兩件不同的事。</p><p>算力的演進路線是CPU→GPU→NPU。GPU時代屬於NVIDIA。劉峻誠押注的是NPU時代——讓AI的推論在終端設備上完成，不依賴雲端，資料留在本地。他創辦的Kneron做的正是這件事。</p><p>他呼應了陳冲的戰國框架：在AI半導體這個新賽局裡，台灣面臨的選擇同樣是合縱還是連橫。他的答案是加強核心競爭力，讓自己成為誰都需要的那個位置。</p><hr><h2 id="四、吳漢章與陳縕儂-算力與ai應用的現況" tabindex="-1">四、吳漢章與陳縕儂：算力與AI應用的現況 <a class="header-anchor" href="#四、吳漢章與陳縕儂-算力與ai應用的現況" aria-label="Permalink to &quot;四、吳漢章與陳縕儂：算力與AI應用的現況&quot;">​</a></h2><p>台智雲總經理吳漢章帶來的是台灣算力建設的進度報告。台智雲的超級電腦落在台南，全球超算排名第29，算力約等於2,300萬台筆電的總和。晶創26計畫在補貼算力基礎設施，另外還有主權AI模型代工服務——幫各機構打造不外流的本地模型。</p><p>「算力主權」這個概念，跟前面幾位講者說的供應鏈主權、資料主權，其實是同一個方向的不同面向。</p><p>台大資工教授陳縕儂做的是AI能力的整體科普梳理：感知（語音辨識、影像辨識、天氣預測）、合成（生成式AI）、推論（知識管理、稅務自動化、教育教材生成）。她列舉了藥物研發、數學問題求解、人機協作等應用方向。</p><p>作為一個整體的概念地圖，脈絡清楚，適合還在建立AI基礎認識的聽眾。</p><hr><h2 id="五、周維昆-ai在國防的落地" tabindex="-1">五、周維昆：AI在國防的落地 <a class="header-anchor" href="#五、周維昆-ai在國防的落地" aria-label="Permalink to &quot;五、周維昆：AI在國防的落地&quot;">​</a></h2><p>銘旺科技董事長周維昆談的是AI在國防的應用，代表作是COBRA無人機系統。</p><p>這個部分討論得比較簡短，但有一個訊息很明確：AI不只是產業工具，也是國防能力的一部分。從劉峻誠的邊緣AI到周維昆的無人機，底層邏輯是一樣的——自主運算、不依賴外部。</p><hr><h2 id="聽完六場-我想到了什麼" tabindex="-1">聽完六場，我想到了什麼 <a class="header-anchor" href="#聽完六場-我想到了什麼" aria-label="Permalink to &quot;聽完六場，我想到了什麼&quot;">​</a></h2><p><strong>第一，這六個人其實在講同一件事。</strong></p><p>陳冲說合縱、吳田玉說槓桿、劉峻誠說加強核心競爭力、吳漢章說算力主權、周維昆說自主。換個角度看，全都是「如何讓台灣在新秩序裡不只是被動的零件」。</p><p><strong>第二，劉峻誠用伊朗的例子讓我一直在想。</strong></p><p>擁有資源，但換不成戰略位置。放到AI時代——台灣有晶片製造能力，但模型、數據、應用生態這些東西現在在誰手上？整場論壇沒有人給出完整的答案。</p><p><strong>第三，陳冲的留白。</strong></p><p>五個選項放在台上，他把問題問清楚了，但沒有替台灣選。這種隱諱的風格，我坐在台下一直在想：是因為答案太政治敏感，還是他認為這個問題本來就應該由台灣社會自己去回答？</p><p>也許兩者都是。</p><hr><h2 id="後記-我自己的application層" tabindex="-1">後記：我自己的Application層 <a class="header-anchor" href="#後記-我自己的application層" aria-label="Permalink to &quot;後記：我自己的Application層&quot;">​</a></h2><p>聽完整場，我忍不住對照了一下自己的現況。</p><p>黃仁勳曾經提過一個AI產業的架構圖，從底層到頂層：Energy、Chips、Infrastructure、Models、Applications。台灣在Chips很強，Infrastructure在建，但最頂層的Applications——真正面向使用者、產生黏性的產品——還很薄弱。</p><p>然後我回頭看自己手上在用的東西：我的新創專案Migato用的是中國模型（比較便宜）、做AI影片用的是Kling、最近在測試的還有Seadance 2.0、剪映——全部都是中國的工具。</p><p>一邊聽台灣要掌握AI主權，一邊發現自己的Application層從頭到尾都在中國生態裡跑。這個矛盾不只是我個人的，是台灣整個Application層的現實縮影。</p><p>中國的AI應用工具跑得快、功能強、價格便宜。對創業者來說，這是很難抗拒的選擇。但如果有一天地緣政治讓這條線斷掉，或者客戶開始問「你的AI是哪裡來的」，現在的每一個選擇都會變成風險。</p><p>台灣的AI主權討論，在Application層追上來之前，對很多實際在做產品的人來說，還是有點遙遠。</p><p>但我也在想，也許這正是施力的地方。</p><p>我自己在做的產品裡，Ambi是邊緣AI，資料在本地運算，不依賴雲端。Migato目前還是跑在雲端，用的也是中國模型——這是現實的成本選擇，我不打算假裝它不存在。但有一件事我們從一開始就確定了：使用者的記憶資料存在自己的伺服器上，不流向中國。架構上模型供應商也保持可替換，不綁死在單一來源。</p><p>我沒辦法一個人把台灣的Application層補起來。但我可以在自己做的產品裡，把「不依賴外部」這件事盡可能做進架構裡，然後把這個選擇說清楚。</p><p>也許台灣的AI主權，就是這樣一個產品、一個選擇地慢慢積累出來的。</p><hr>',67)])])}const A=a(o,[["render",n]]);export{d as __pageData,A as default};
